-- The 18 Blockchain & Web3 interactive courses now have full lessons, labs and tests,
-- so their course products can be sold. Existing rows were seeded inactive because the
-- courses had no content then; new databases seed them active automatically.
UPDATE pay_products SET active = 1 WHERE kind = 'course' AND sku IN ('course-intro-blockchain-web3','course-blockchain-blocks-hashing-consensus','course-cryptocurrency-digital-assets-fundamentals','course-blockchain-architecture-networks','course-ethereum-smart-contracts','course-solidity-programming-beginners','course-build-first-blockchain-dapp','course-advanced-solidity-development','course-smart-contract-security-auditing','course-token-development-erc-standards','course-nfts-decentralized-applications','course-web3-development-javascript-nodejs','course-blockchain-php-nodejs','course-production-ready-web3-apps','course-blockchain-5-real-world-projects','course-blockchain-enterprise-architecture','course-blockchain-defi','course-blockchain-capstone-project');
